    #include <windows.h>
    #include <stdio.h>

    char* sortedWord(const char* word, char* wbuf)
    {
        char* p1, *p2, *endwrd;
        char t;
        int swaps;

        strcpy(wbuf, word);
        endwrd = wbuf + strlen(wbuf);
        do {
            swaps = 0;
            p1 = wbuf; p2 = endwrd - 1;
            while (p1 < p2) {
                if (*p2 >* p1) {
                    t = *p2; *p2 = *p1; *p1 = t;
                    swaps = 1;
                }
                p1++; p2--;
            }
            p1 = wbuf; p2 = p1 + 1;
            while (p2 < endwrd) {
                if (*p2 >* p1) {
                    t = *p2; *p2 = *p1; *p1 = t;
                    swaps = 1;
                }
                p1++; p2++;
            }
        } while (swaps);
        return wbuf;
    }

    static short cxmap[] = {
        0x06, 0x1f, 0x4d, 0x0c, 0x5c, 0x28, 0x5d, 0x0e, 0x09, 0x33, 0x31, 0x56,
